## Example

A complete workflow: split, engineer features, tune, finalize, and deploy.


::: {.cell}

```{.r .cell-code}
library(tidymodels)

# Split data and make CV folds
set.seed(857)

splits <- ames |>
  initial_split(prop = 0.8)
train <- training(splits)
folds <- train |>
  vfold_cv(v = 5)

# Feature engineering in a recipe
rec <- recipe(
  Sale_Price ~ Gr_Liv_Area + Year_Built + Bldg_Type,
  data = train
) |>
  step_log(Gr_Liv_Area, base = 10) |>
  step_dummy(all_nominal_predictors()) |>
  step_normalize(all_numeric_predictors())

# Model with parameters to tune
mod <- decision_tree(
  cost_complexity = tune(),
  tree_depth = tune()
) |>
  set_engine("rpart") |>
  set_mode("regression")

# Bundle into a workflow
wf <- workflow() |>
  add_recipe(rec) |>
  add_model(mod)

# Tune over the folds
res <- wf |>
  tune_grid(
    resamples = folds,
    grid = 10
  )

# Finalize best, refit, test once
best <- res |>
  select_best(metric = "rmse")
final <- wf |>
  finalize_workflow(best) |>
  last_fit(splits)

collect_metrics(final)
```

